%[text] # 处理XL-80 & IDS-3010导出的数据
close all;
clear; clc;
cd(fileparts(which("start_up.m")));
tic;

set(groot, 'DefaultAxesFontName', 'Times New Roman', 'DefaultAxesFontSize', 12);
set(groot, 'DefaultTextFontName', 'Times New Roman', 'DefaultTextFontSize', 12);
set(groot, 'DefaultAxesXMinorTick', 'on');

GEOMETRIC_ERROR_MAP = 'data/X_positioning_error.mat';

defaultPath = char('D:\Sync\syncthing\Data\202406-mms-dynamics\ids results mat\20240530 IDS\XD_Y3000_A3J80.mat');
% defaultPath = char('D:\Sync\syncthing\Data\202406-mms-dynamics\xl80 results\20240530 xl80\XD-Y0_A3J80.csv');
[fileName, fileLocatiion, idx] = uigetfile({ ...
    '*.mat','MAT files'; ...
    '*.csv','comma-separated-value files'; ...
    '*.*','All files' ...
    },'Select the data file', defaultPath);
FILE_PATH = fullfile(fileLocatiion, fileName);

switch idx
    case 1
        % .mat file
        measData = load(FILE_PATH);
        % measData = struct2table(measData); 
    case 2
        % .csv file: xl-80 results
        fid = fopen(FILE_PATH);
        for ii = 1:100
            tline = fgetl(fid);
            if contains(tline,'Time,Measurement')
                break;
            end
        end
        fclose(fid);
        
        opts = detectImportOptions(FILE_PATH,"FileType","delimitedtext","NumHeaderLines",ii - 1);
        dataTable = readtable(FILE_PATH,opts);
        measData = struct("Time",dataTable.Time,"Displacement",dataTable.Measurement);
        measData.Displacement = -1.*measData.Displacement;
end

% Fetch the theoretical acceleration from the name of the file
theoAccelPattern = 'A(\d+)'; % 匹配"A"后面的数字
match = regexp(fileName, theoAccelPattern, 'tokens');
theoAccel = str2double(match{1}{1});
clear theoAccelPattern match;

% Parameters for character extraction
DISP_MinPeakProminence = 10; % Measured point A, B, D
VELO_MinPeakProminence = 10;
ACCEL_MinPeakProminence = 0.5;
isFluctuation = false; % false for measured A, B, C, and J5 in D;
%%
%[text] ## --------------------------- 位移数据处理：开始方向确认 ---------------------------
%[text] 不同的数据，测量的开始位置和方向并未统一，需要在此统一为：
%[text] X轴数据以X=-1000为起点沿负方向遍历，Y轴数据以Y=0为起点沿正方形遍历（即与几何误差表一致）  
%[text] **不同测点的情况会有不同，在换测点时必须留意此处！！！！！**
%[text] **X轴A、D测点只需要将起始点平移到X=-1000即可**
%[text] **X轴B测点需取反，再将起始点平移到X=-3000**
%[text] **X轴C测点**
% X轴A、D测点：X=-1000~X=-5500
% measData.Displacement = measData.Displacement - 1000 + measData.Displacement(1);
% X轴B测点：X=-3000~X=-7000
% measData.Displacement = -1 * measData.Displacement - 3000 + measData.Displacement(1);
% X轴C测点：X=-4200~X=-4300
% measData.Displacement = -1 * measData.Displacement - 4200 + measData.Displacement(1);
% X轴C测点：X=-6900~X=-7000
% measData.Displacement = -1 * measData.Displacement - 6900 + measData.Displacement(1);

fig1 = figure('Name', '【IDS】位移原始图像'); %[output:96e69bd5]
ax1 = axes(fig1); %[output:96e69bd5]
plot(ax1, measData.Time, measData.Displacement); %[output:96e69bd5]
hold(ax1, "on"); %[output:96e69bd5]
xlabel(ax1, 'Time (s)'); %[output:96e69bd5]
ylabel(ax1, 'Displacement (mm)'); %[output:96e69bd5]
drawnow;

clear fig1 ax1;
%%
%[text] ## ---------------------------------- 位移数据处理 ----------------------------------
% if isempty(gcp('nocreate'))
%     parpool;
% end
% tmpDispSmooth = zeros(size(tmpDisp));
% block_size = 10000;
% num_blocks = ceil(length(tmpDisp) / block_size);
% % 并行分块处理数据
% tic
% for i = 1:num_blocks
%     temp_smooth = zeros(1, block_size);
% 
%     start_idx = (i-1) * block_size + 1;
%     end_idx = min(i * block_size, length(tmpDisp));
% 
%     temp_smooth(1:(end_idx-start_idx+1)) = smoothdata(tmpDisp(start_idx:end_idx), ...
%         'sgolay', 51, 'SamplePoints', tmpTime(start_idx:end_idx), 'Degree', 2);
%     tmpDispSmooth(start_idx:end_idx) = temp_smooth(1:(end_idx-start_idx+1));
% end
% toc
% tmpDispSmooth = smoothdata(tmpDisp, 'sgolay', 7, 'SamplePoints', tmpTime, 'Degree', 3);
% hold on;
% plot(tmpTime, tmpDispSmooth);


% ------------ 滤波与抽样 ------------
% Data low-pass filtering for denoising
WAVE_NAME = 'sym9'; % 小波基
NUM_LEVEL = min(21, wmaxlev(length(measData.Displacement),WAVE_NAME)); % 分解层数，越高越平滑
dispWavelet = wdenoise(measData.Displacement,NUM_LEVEL, ...
    Wavelet=WAVE_NAME, ...
    DenoisingMethod='Bayes', ...
    ThresholdRule='Soft', ...
    NoiseEstimate='LevelIndependent');

% dispWavelet = measData.Displacement;

% Data downsampling
DOWN_SAMPLE_RATE = 10;
downsampleTime = measData.Time(1:DOWN_SAMPLE_RATE:end);
downsampleDisp = dispWavelet(1:DOWN_SAMPLE_RATE:end);

% 计算滤波抽样后的时间间隔和采样率
timeTerminal = downsampleTime(2) - downsampleTime(1);
sampleRate = 1 / timeTerminal;

% ------------ 定位误差滤除 ------------
% load the geometric error fitting result
load(GEOMETRIC_ERROR_MAP);

% take the geometric error into account
geometricError = ppval(geometric_error_pp, downsampleDisp);
geometricRemoveDisp = downsampleDisp - geometricError;

% plot the geometric error
fig2 = figure('Name', '【IDS】位移定位误差滤除'); %[output:191ce4de]
ax2 = axes(fig2); %[output:191ce4de]
yyaxis(ax2, "left"); %[output:191ce4de]
plot(ax2, downsampleTime, downsampleDisp); %[output:191ce4de]
ylabel(ax2, "Original Displacement (mm)"); %[output:191ce4de]
y_min = min(downsampleDisp);
y_max = max(downsampleDisp);
if y_min > 0
    ylim([0, y_max]);
elseif y_max < 0
    ylim([y_min, 0]);
else
    ylim([y_min, y_max]); %[output:191ce4de]
end
yyaxis(ax2, "right"); %[output:191ce4de]
area(ax2, downsampleTime, geometricError, 0, ... %[output:191ce4de]
    "EdgeColor", [0.8500 0.3250 0.0980], "EdgeAlpha", 0.5, ... %[output:191ce4de]
    "FaceColor", [0.8500 0.3250 0.0980], "FaceAlpha", 0.1); %[output:191ce4de]
ylabel(ax2, "Geometric Error (mm)"); %[output:191ce4de]
xlabel(ax2, "Time (s)"); %[output:191ce4de]

% ------------ 计算滤波后的速度 ------------
measData.veloTime = 0.5 * (downsampleTime(1:end - 1) + downsampleTime(2:end));
measData.velo = 60 * diff(downsampleDisp) ./ diff(downsampleTime);

% 画位置和速度的滤波图像
figure('name', '【IDS】位移滤波效果'); %[output:63e971fa]
tiledlayout(2, 1); %[output:63e971fa]
ax1 = nexttile; %[output:63e971fa]
plot(measData.Time, measData.Displacement, 'DisplayName', 'Raw'); %[output:63e971fa]
hold on; %[output:63e971fa]
plot(measData.Time, dispWavelet, 'DisplayName', 'Filtered'); %[output:63e971fa]
legend; %[output:63e971fa]
ylabel('Displacement (mm)'); %[output:63e971fa]
ax2 = nexttile; %[output:63e971fa]
plot(0.5 * (measData.Time(1:end - 1) + measData.Time(2:end)), ... %[output:63e971fa]
    60 * diff(measData.Displacement) ./ diff(measData.Time), ... %[output:63e971fa]
    'LineWidth', 1, 'DisplayName', 'Original'); %[output:63e971fa]
hold on; %[output:63e971fa]
plot(measData.veloTime, measData.velo, 'LineWidth', 1, 'DisplayName', 'Filtered'); %[output:63e971fa]
legend; %[output:63e971fa]
% ylim([min(measData.velo), max(measData.velo)]);
xlabel('Time (s)'); %[output:63e971fa]
ylabel('Velocity (mm/min)'); %[output:63e971fa]
linkaxes([ax1, ax2], 'x'); %[output:63e971fa]
drawnow;

% 存储位移数据处理结果
measData.Time = downsampleTime;
measData.Displacement = geometricRemoveDisp;

clear downsampleTime downsampleDisp geometricRemoveDisp dispWavelet ax2 fig2;
%%
%[text] ## --------------------------- 速度滤波处理（为了加速度计算） ---------------------------
% 速度曲线滤波
% measData.velo_filtered = measData.velo;
% 高斯滤波，不能解决匀加减速过程，或者匀速过程抖动对加速度计算的影响。
% siemensData.velo1_filtered = filter_gaussian(100, 1, siemensData.velo);
% 三次样条加权平滑
% veloPeaks = peak_segmentation(measData.veloTime, measData.velo, [], ...
%     "IsNormalization", false, ...
%     "MinPeakDistance", 4, "MinPeakProminence", 10000, 'MinPeakWidth', 1);
% weights = ones(size(measData.veloTime));
% weightFactor = 1;
% weights(veloPeaks.ind) = weights(veloPeaks.ind) * weightFactor;
sp = spaps(measData.veloTime, measData.velo, 5000000, [], 2);
measData.velo_filtered = fnval(sp, measData.veloTime);
% clear sp veloPeaks;
% 小波
% WAVE_NAME = 'sym9'; % 小波基
% NUM_LEVEL = min(21, wmaxlev(length(measData.velo),WAVE_NAME)); % 分解层数，越高越平滑
% measData.velo_filtered = wdenoise(measData.velo, NUM_LEVEL, ...
%     Wavelet=WAVE_NAME, ...
%     DenoisingMethod='Bayes', ...
%     ThresholdRule='Soft', ...
%     NoiseEstimate='LevelIndependent');

% 计算加速度
measData.accelTime = 0.5 * (measData.veloTime(1:end - 1) + measData.veloTime(2:end));
measData.accel = diff(measData.velo_filtered) ./ diff(measData.veloTime) ./ 60000;

% 查看速度滤波的效果 （结果就是滤波作用不大）
figure('Name','【IDS】速度滤波结果'); %[output:3a46b195]
tiledlayout(3, 1); %[output:3a46b195]
ax1 = nexttile; %[output:3a46b195]
plot(measData.veloTime, measData.velo, 'DisplayName', 'Raw'); %[output:3a46b195]
hold on; %[output:3a46b195]
plot(measData.veloTime, measData.velo_filtered, 'DisplayName', 'Filtered'); %[output:3a46b195]
legend; %[output:3a46b195]
title('Velocity curve before & after filtering'); %[output:3a46b195]
ylabel('Velocity (m/s^2)'); %[output:3a46b195]
set(gca, "XTickLabel", []); %[output:3a46b195]

ax2 = nexttile; %[output:3a46b195]
plot(measData.accelTime, diff(measData.velo) ./ diff(measData.veloTime) ./ 60000, ... %[output:3a46b195]
    "Color", [0, 0.4450, 0.7410]); %[output:3a46b195]
title('Acceleration curve before filtering'); %[output:3a46b195]
ylabel('Acceleration (m/s^2)'); %[output:3a46b195]
set(gca, "XTickLabel", []); %[output:3a46b195]

ax3 = nexttile; %[output:3a46b195]
plot(measData.accelTime, diff(measData.velo) ./ diff(measData.veloTime) ./ 60000, ... %[output:3a46b195]
    'DisplayName', 'Original', "Color", [0, 0.4450, 0.7410] * 0.5 + [1, 1, 1] * 0.5); %[output:3a46b195]
hold on; %[output:3a46b195]
plot(measData.accelTime, measData.accel, 'DisplayName', 'Filtered'); %[output:3a46b195]
ylim(1.1 * [min(measData.accel), max(measData.accel)]) %[output:3a46b195]
title('Acceleration curve after filtering'); %[output:3a46b195]
xlabel('Time (s)'); %[output:3a46b195]
ylabel('Acceleration (m/s^2)'); %[output:3a46b195]
legend; %[output:3a46b195]
linkaxes([ax1, ax2, ax3], 'x'); %[output:3a46b195]
drawnow;
%%
% fc = 5;
% % 输入信号分解
% x_sig_est = lowpass(diff(measData.Displacement), fc, 1/(measData.Time(2) - measData.Time(1)));
% x_noise_est = diff(measData.Displacement) - x_sig_est;
% 
% % 输出信号分解
% y_sig_est = lowpass(measData.velo_filtered, fc, sampleRate);
% y_noise_est = measData.velo_filtered - y_sig_est;
% 
% snr_in_est  = 10*log10(sum(x_sig_est.^2) / sum(x_noise_est.^2));
% snr_out_est = 10*log10(sum(y_sig_est.^2) / sum(y_noise_est.^2));
