% plot(measData.accelTime, measData.accel);
% 画加速度原始图像
% fig5 = figure('name', '【IDS】加速度图像');
% hLine = plot(measData.accelTime, measData.accel, 'LineWidth', 1);
% hAxes = ancestor(hLine, 'Axes');
% hold on;
% % title(hAxes, 'Acceleration 1 vs 2');
% ylim([min(measData.accel), max(measData.accel)]);
% xlabel('Time (s)');
% ylabel('Acceleration (m/s^2)');
%%
%[text] ## --------------------------- 位移分段分析 ---------------------------
%[text] 使用findpeaks函数，排除噪声并寻找所有局部最值。计算局部最值离理想值的差值，作为偏差
shiftTime = ceil(0.1 * sampleRate); % the time interval around the peak/valley value
dispPeaks = peak_segmentation(measData.Time, measData.Displacement, [], ...
    "IsNormalization", false, "MinPeakProminence", DISP_MinPeakProminence);
% calculate the disprange
dispPeaks.dispRange(:, 1) = dispPeaks.ind - shiftTime;
dispPeaks.dispRange(:, 2) = dispPeaks.ind + shiftTime + 1;
% add a line in the end, which is more convenient to be copied into excel
tmp = table(NaN, NaN, NaN, NaN, NaN, NaN, NaN, [NaN, NaN], 'VariableNames', dispPeaks.Properties.VariableNames);
dispPeaks(end + 1, :) = tmp; 
if strcmp(fileName(2), 'C')
    % if Measured point C, then eliminate the final peak value of each segment
    dispPeaksforAccel = dispPeaks;
    peakLength = size(dispPeaks, 1);
    for ii = 12 .* (1:floor(peakLength / 12))
        dispPeaks(ii, :) = tmp;
    end
end

plot_peaks(measData.Time, measData.Displacement, dispPeaks(1:2:end - 1, :), dispPeaks(2:2:end, :), ... %[output:group:2c9d2398] %[output:816462bb]
    "PlotName", "【IDS】位移峰值"); %[output:group:2c9d2398] %[output:816462bb]
drawnow;
%%
%[text] ## --------------------------- 速度指标计算 ---------------------------
ADJACENT_PARAM = 0.2 * sampleRate; % A3J5要改成1 * sampleRate
% Extract velocity segments from the signal
[velocitySegment, desiredValue, tLim1End] = velocity_segmentation(measData.velo_filtered, ADJACENT_PARAM, 'case', 'IDS');

% Draw each segments of the velocity signal
fig5 = figure('Name', '【IDS】速度指标计算'); %[output:1732630b]
figPos = get(fig5, "Position");
screenPos = get(0, 'ScreenSize');
set(fig5, "Position", [figPos(1), figPos(2) - figPos(4), figPos(3), figPos(4)]); %[output:1732630b]
t1 = tiledlayout(fig5, 3, 1, "TileSpacing", "tight", 'Padding', 'tight'); %[output:1732630b]
n1 = nexttile(t1, 1, [2, 1]); %[output:1732630b]
hLine = plot(measData.veloTime, measData.velo_filtered, 'LineWidth', 0.5, 'DisplayName', 'Velocity'); %[output:1732630b]
hold on; %[output:1732630b]
for ii = 1:length(desiredValue)
    % if ~isnan(desiredValue(ii))
        plotObj = plot(measData.veloTime(velocitySegment(ii, 1):velocitySegment(ii, 2)), ... %[output:1732630b]
            measData.velo_filtered(velocitySegment(ii, 1):velocitySegment(ii, 2)), ... %[output:1732630b]
            'LineWidth', 1.25, 'LineStyle', '--'); %[output:1732630b]
        plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
    % end
end
sca1 = scatter(measData.veloTime(velocitySegment(:, 1)), measData.velo_filtered(velocitySegment(:, 1)), ... %[output:1732630b]
    36, 'MarkerEdgeColor', [0.8500 0.3250 0.0980], 'MarkerFaceColor', [0.8500 0.3250 0.0980], ... %[output:1732630b]
    'DisplayName', 'Strat Location', 'Marker', 'o'); %[output:1732630b]
sca2 = scatter(measData.veloTime(velocitySegment(:, 2)), measData.velo_filtered(velocitySegment(:, 2)), ... %[output:1732630b]
    12, 'MarkerEdgeColor', [0.9290 0.6940 0.1250], 'MarkerFaceColor', [0.9290 0.6940 0.1250], ... %[output:1732630b]
    'DisplayName', 'End Location', 'Marker', 'o'); %[output:1732630b]
legend('Location', 'best'); %[output:1732630b]
% title(n1, 'Segmented Velocity');
hAxes = ancestor(hLine, 'Axes');
tLim = [0, measData.veloTime(tLim1End) + 5];
plotObj = plot(tLim, [5000, 5000], 'LineStyle', '--', 'LineWidth', 0.25, 'Color', [0.4, 0.4, 0.4]); %[output:1732630b]
plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
plotObj = plot(tLim, [-5000, -5000], 'LineStyle', '--', 'LineWidth', 0.25, 'Color', [0.4, 0.4, 0.4]); %[output:1732630b]
plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
plotObj = plot(tLim, [30000, 30000], 'LineStyle', '--', 'LineWidth', 0.25, 'Color', [0.4, 0.4, 0.4]); %[output:1732630b]
plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
plotObj = plot(tLim, [-30000, -30000], 'LineStyle', '--', 'LineWidth', 0.25, 'Color', [0.4, 0.4, 0.4]); %[output:1732630b]
plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
hAxes.XLim = tLim; %[output:1732630b]
ylabel('Velocity (mm/min)'); %[output:1732630b]

% Initialize for the velocity parameter struct, then changed into table
veloParam = struct("peakValue", {}, "peakError", {}, "peakMoment", {}, ...
    "steadyStateValue", {}, "steadyStateError", {}, "steadyStateMoment", {}, ...
    "riseTime", {}, "noiseLevel", {}, "overshoot", {}, ...
    "oscillationFrequency", {}, "settlingTime", {}, ...
    "peakValue0", {}, "peakError0", {}, "peakMoment0", {});

% A different method is used for thee measurement point D
% if strcmp(fileName(2), 'D')
%     isFluctuation = true;
% else
%     isFluctuation = false;
% end

% Calculate the velocity parameters for each segments
for ii = 1:size(velocitySegment, 1)
    % diffVelocitySegment = velocitySegment1(ii + 1) - velocitySegment1(ii);
    % if diffVelocitySegment > 1
    %     desiredValue = 5000; 
    % end
    % determine the desired value
    veloParam(ii) = velo_param( ...
        measData.veloTime(velocitySegment(ii, 1):velocitySegment(ii, 2)), ...
        measData.velo_filtered(velocitySegment(ii, 1):velocitySegment(ii, 2)), desiredValue(ii), ...
        'MinPeakProminence', VELO_MinPeakProminence, "Fluctuation", isFluctuation);
    % plotting for debug
    % plotObj = scatter(measData.veloTime(velocitySegment(ii, 1)) + veloParam(ii).peakMoment, ...
    %     veloParam(ii).peakValue);
    % plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
    % plotObj = scatter(measData.veloTime(velocitySegment(ii, 2)) - veloParam(ii).peakMoment0, ...
    %     veloParam(ii).peakValue0);
    % plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
    % drawnow;
end

% Add the item "startMoment" for each elements, and all the time-variables should be shifted 
%   considering the effect of the small overshoot at the beginning of the velocity-shifting process
for ii = 2:size(velocitySegment, 1)
    veloParam(ii).startMoment = measData.veloTime(velocitySegment(ii, 1)) - veloParam(ii - 1).peakMoment0;
    veloParam(ii).startValue = veloParam(ii - 1).peakValue0;
    veloParam(ii).steadyStateMoment = veloParam(ii).steadyStateMoment + veloParam(ii - 1).peakMoment0;
    veloParam(ii).peakMoment = veloParam(ii).peakMoment + veloParam(ii - 1).peakMoment0;
    veloParam(ii).riseTime = veloParam(ii).riseTime + veloParam(ii - 1).peakMoment0;
    veloParam(ii).settlingTime = veloParam(ii).settlingTime + veloParam(ii - 1).peakMoment0;
end

% the startmoment of the first segment should be calculated here, i.e., the peak location before the 1st segment
[~, ind] = findpeaks(abs(measData.velo_filtered(1:velocitySegment(1, 1))), "NPeaks", 1, 'SortStr', 'descend');
veloParam(1).startMoment = measData.veloTime(ind);
veloParam(1).startValue = measData.velo_filtered(ind);
deltaMoment = measData.veloTime(velocitySegment(1, 1) - ind);
veloParam(1).steadyStateMoment = veloParam(1).steadyStateMoment + deltaMoment;
veloParam(1).peakMoment = veloParam(1).peakMoment + deltaMoment;
veloParam(1).riseTime = veloParam(1).riseTime + deltaMoment;
veloParam(1).settlingTime = veloParam(1).settlingTime + deltaMoment;

drawnow;
pause(2);
delete(sca1); delete(sca2); %[output:1732630b]
scatter([veloParam.startMoment], [veloParam.startValue], 36, ... %[output:1732630b]
    'MarkerEdgeColor', [0.8500 0.3250 0.0980], 'MarkerFaceColor', [0.8500 0.3250 0.0980], ... %[output:1732630b]
    'DisplayName', 'Seperate Location', 'Marker', 'diamond', 'MarkerFaceAlpha', 0.3); %[output:1732630b]
% plotObj = line(meshgrid([veloParam.startMoment], 1:2), max(measData.velo_filtered) * ndgrid([-1, 1], 1:38), ...
%     "Color", [0.8500 0.3250 0.0980], "LineStyle", "-.");
% plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
scatter([veloParam.startMoment] + [veloParam.peakMoment], [veloParam.peakValue], 36, ... %[output:1732630b]
    'MarkerEdgeColor', [0.9290 0.6940 0.1250], 'MarkerFaceColor', [0.9290 0.6940 0.1250], ... %[output:1732630b]
    'DisplayName', 'Peaks', 'Marker', 'o', 'MarkerFaceAlpha', 0.3); %[output:1732630b]
scatter([veloParam.startMoment] + [veloParam.steadyStateMoment], [veloParam.steadyStateValue], 36, ... %[output:1732630b]
    'MarkerEdgeColor', [0.4660 0.6740 0.1880] * 0.5, ... %[output:1732630b]
    'DisplayName', 'Steady State', 'Marker', '*'); %[output:1732630b]

% change the data structure from struct to table, which is easier to duplicate
veloParam = struct2table(veloParam);

% 画图展示速度评价参数
nexttile(t1, 3); %[output:1732630b]
yyaxis left; %[output:1732630b]
bar(measData.veloTime(velocitySegment(:, 1)), veloParam.peakError, 1, "LineStyle", "none"); %[output:1732630b]
ylabel('Peak error (mm/min)'); %[output:1732630b]
xlabel('Time (s)'); %[output:1732630b]
yyaxis right; %[output:1732630b]
plot(measData.veloTime(velocitySegment(:, 1)), 100*veloParam.overshoot, ... %[output:1732630b]
    "Marker", "diamond", "Color", [0.8500 0.3250 0.0980], ... %[output:1732630b]
    "MarkerEdgeColor", [0.8500 0.3250 0.0980], "MarkerFaceColor", [0.8500 0.3250 0.0980]); %[output:1732630b]
ylabel('Overshoot'); %[output:1732630b]
ytickformat('%.1g%%'); %[output:1732630b]
xlim(tLim); %[output:1732630b]
legend("Peak error", "Overshoot percent", "Location", "best"); %[output:1732630b]
% nexttile(t1, 10, [1, 1]);
% yyaxis left;
% plot(measData.veloTime(velocitySegment(:, 1)), veloParam.riseTime, 'o-', ...
%     'MarkerSize', 3, "MarkerFaceColor", [0 0.4470 0.7410]);
% hold on;
% yyaxis right;
% plot(measData.veloTime(velocitySegment(:, 1)), veloParam.settlingTime, 'square-', ...
%     'MarkerSize', 3, "MarkerFaceColor", [0.8500 0.3250 0.0980]);
% xlim(tLim);
% legend("Rising time", "Setting time", "Location", "best");
% nexttile(t1, 11, [1, 1]);
% plot(measData.veloTime(velocitySegment(:, 1)), veloParam.noiseLevel, ...
%     "Marker", "o", "MarkerSize", 3);
% xlim(tLim);
% legend("Noise level", "Location", "best");
% nexttile(t1, 12, [1, 1]);
% plot(measData.veloTime(velocitySegment(:, 1)), veloParam.oscillationFrequency, ...
%     "Marker", "o", "MarkerSize", 3);
% xlim(tLim);
% legend("Oscillation frequency", "Location", "best");
drawnow;
%%
%[text] ## ------------------------------ 加速度指标计算 ------------------------------
%[text] 由于加速度数据的鲁棒性远远不及位移和速度，故分段和指标计算后的数据，单独检查后再拷贝到excel文件中
[accelPeaks,accelValleys] = peak_segmentation(measData.accelTime, measData.accel, ... %[output:group:5028f845] %[output:8acf4b48]
    theoAccel, "PlotName", "【IDS】加速度峰谷值", "MinPeakDistance", ACCEL_MinPeakProminence); %[output:group:5028f845] %[output:8acf4b48]
drawnow;
%%
%[text] ## --------------------------------- 指标整理 ---------------------------------
%[text] 位移、速度指标按Excel记录表格整理
paramExcel = save_excel(dispPeaks, veloParam);

% 加速度指标另外计算
num = size(paramExcel, 1);
if strcmp(fileName(2), 'C') %[output:group:56cf905e]
    accelExcel = accel_param2excel_C(measData.accelTime, measData.accel, num, ...
        accelPeaks, accelValleys, dispPeaksforAccel, "PlotName", "【IDS】加速度数据提取动画");
else
    accelExcel = accel_param2excel(measData.accelTime, measData.accel, num, ... %[output:0249dc17]
        accelPeaks, accelValleys, dispPeaks, "PlotName", "【IDS】加速度数据提取动画"); %[output:0249dc17]
end %[output:group:56cf905e]

% 合并加速度表格和位移速度表格
paramExcel = [paramExcel, accelExcel];
%%
%[text] ## ----------------------------------- 收尾 -----------------------------------
[pathstr, name, ~] = fileparts(FILE_PATH);
filePath1 = fullfile(pathstr, name);
% if ~isfolder(filePath1)
%     mkdir(filePath1);
% end
% fig_save(filePath1);

% 图像平铺
% fig_tiled;
% fig_modal;

fprintf("The data extraction process for the file %s is completed. \n", fileName); %[output:82d3b88c]
t = toc %[output:96109903]

